import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"并行与生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/concurrency-lifecycle.md","filePath":"architecture/concurrency-lifecycle.md","lastUpdated":null}'),n={name:"architecture/concurrency-lifecycle.md"};function o(i,e,c,s,d,p){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="并行与生命周期" tabindex="-1">并行与生命周期 <a class="header-anchor" href="#并行与生命周期" aria-label="Permalink to &quot;并行与生命周期&quot;">​</a></h1><p>HarnessVLN 的默认并行单位是<strong>完整 Task</strong>，不是 Task 内单步。并行策略同时受组件作用域、原生 资源限制和跨 Task 写入影响。</p><h2 id="runner-的有界并行" tabindex="-1">Runner 的有界并行 <a class="header-anchor" href="#runner-的有界并行" aria-label="Permalink to &quot;Runner 的有界并行&quot;">​</a></h2><p><code>BenchRunner</code> 使用一个容量为 <code>parallelism * 2</code> 的队列：producer 流式读取 <code>benchmark.cases()</code>， 多个 consumer 各自构造完整 stack 并调用 <code>run_task</code>。结果可能乱序完成，最后按输入 index 排序。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Benchmark.cases() -&gt; bounded queue -&gt; worker 0 -&gt; whole Task A</span></span>\n<span class="line"><span>                                  -&gt; worker 1 -&gt; whole Task B</span></span>\n<span class="line"><span>                                  -&gt; worker 2 -&gt; whole Task C</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>该设计不会一次把百万级 split 全部装入内存，<code>max_cases</code> 也在 producer 侧截断。</p><h2 id="task-内有哪些并发" tabindex="-1">Task 内有哪些并发 <a class="header-anchor" href="#task-内有哪些并发" aria-label="Permalink to &quot;Task 内有哪些并发&quot;">​</a></h2><p>一个 Task 内存在协程并发，但控制权仍属于 Agent：</p><ul><li><code>Agent.run</code> 与 <code>Environment.wait_terminal</code> 同时等待；</li><li>VLN Job 可以作为后台协程或独立 worker 进程运行；</li><li>RPC worker 可发出异步反向 tool call；</li><li>ToolBus 允许只读调用并行，并追踪在途写调用；</li><li>Memory 由自身实现决定是否并行查询。</li></ul><p>“Agent 与 VLN 同时运行”不意味着 Runner 分别调度它们。VLN 的生命周期由 navigator 管理， Agent 通过 Job 工具委托和观察状态。</p><h2 id="作用域与实例数" tabindex="-1">作用域与实例数 <a class="header-anchor" href="#作用域与实例数" aria-label="Permalink to &quot;作用域与实例数&quot;">​</a></h2><p>假设一个 Run 有 100 个 case：</p><table tabindex="0"><thead><tr><th>配置</th><th style="text-align:right;">Agent 实例</th><th style="text-align:right;">Env 实例</th><th style="text-align:right;">VLN 实例/worker</th><th style="text-align:right;">Memory 实例</th></tr></thead><tbody><tr><td>全部 task-scope</td><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">100</td></tr><tr><td>VLN <code>scope: run</code></td><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">1</td><td style="text-align:right;">100</td></tr></tbody></table><p>run-scoped VLN 在 case 之间解除旧 ToolClient 绑定、释放 Job media，再绑定新环境；checkpoint 和 worker PID 保持不变。Run 结束后 <code>ConfiguredStackFactory.close_run()</code> 负责关闭。</p><h2 id="何时必须串行" tabindex="-1">何时必须串行 <a class="header-anchor" href="#何时必须串行" aria-label="Permalink to &quot;何时必须串行&quot;">​</a></h2><p>StackFactory 的 <code>requires_serial</code> 在以下任一条件成立时为真：</p><ul><li>某组件配置 <code>serial: true</code>；</li><li>VLN 使用 <code>scope: run</code>；</li><li>Memory 存在且 <code>writeback</code> 默认为 true。</li></ul><p>此时 <code>runner.parallelism &gt; 1</code> 会在运行前报错，而不是带着共享状态冒险执行。Isaac Kit 是典型的 进程级串行资源；Dummy Landmark Memory 的单文件写回也默认串行。</p><div class="tip custom-block"><p class="custom-block-title">扩展并行的正确方式</p><p>需要多个 Isaac case 并行时，使用多个隔离服务进程并让每个 Environment 独占连接；需要共享 Memory 并行写时，实现事务型存储。不要只删除 <code>serial</code> 标记。</p></div><h2 id="多频-vln-如何保留" tabindex="-1">多频 VLN 如何保留 <a class="header-anchor" href="#多频-vln-如何保留" aria-label="Permalink to &quot;多频 VLN 如何保留&quot;">​</a></h2><p>DualVLN 一类大小脑不同频模型不由 Harness 拆开。一个 Job 在 worker 内维护 System 1、System 2、 帧窗口与连续轨迹；worker 可在需要时主动 <code>nav.observe</code>，推理后调用多个动作或 <code>stand_still</code>。 外部只看到 Job 状态与审计事件。</p><p>这意味着时间尺度分三层：</p><ol><li>Runner 的 Task 调度频率；</li><li>Agent 的 workflow / Job 轮询频率；</li><li>VLN 内部推理与原生 Environment tick 频率。</li></ol><p>三层互不假定一一对应。Isaac 的一个 <code>nav.move.discrete</code> 还可能在中间件中推进最多数千 native tick， 直到高层动作完成。</p><h2 id="取消不是简单-task-cancel" tabindex="-1">取消不是简单 <code>task.cancel()</code> <a class="header-anchor" href="#取消不是简单-task-cancel" aria-label="Permalink to &quot;取消不是简单 `task.cancel()`&quot;">​</a></h2><p>取消时可能存在 GPU 进程、子进程组、文件映射和在途运动。现有实现使用：</p><ul><li>shielded cancel/close，确保调用者被取消时清理仍能收敛；</li><li>worker process group 的 TERM/KILL 兜底与同步 fence；</li><li>Job seal，拒绝已关闭 Job 的新反向调用；</li><li>media release，按 Job 清理 file-backed array；</li><li>ToolBus write fence 与 drain；</li><li>独立记录 cleanup error，不覆盖主异常。</li></ul><p>编写新插件时，<code>stop()</code> 必须幂等、可在部分启动状态调用，并在返回前阻断后续副作用。</p>',28)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
